using GoDental.Application.Common;
using GoDental.Application.DTOs;
using GoDental.Application.Services;
using GoDental.Application.Validators;
using GoDental.Wpf.Dialogs;
using GoDental.Wpf.ViewModels.Operations;
using Microsoft.Extensions.Logging.Abstractions;
namespace GoDental.Tests.Ui;
public sealed class OnlineTests
{
    private static OnlineSourceInput Source()=>new("WEB","https://negocio.example.com/contacto",DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(-6)).Date,"Contacto empresarial");
    private static SaveOnlineProspect Request()=>new(Guid.NewGuid(),0,[],new(){Name="Negocio",Phone="70000000"},Source(),"Registro público");
    private static (OnlineViewModel Vm,UserSession Session,OnlineUiRepository Repo,Dialogs Dialogs) Create(params string[] permissions)
    {var s=new UserSession();s.Begin(new(1,"test","Prueba",1,[],permissions.Length>0?permissions:["COMERCIAL.VER","CLIENTES.VER","COMERCIAL.PROSPECTAR","COMERCIAL.EXCLUSIONES","VENTAS.VER"],false));var repo=new OnlineUiRepository();var dialogs=new Dialogs();return(new(new(repo,s),dialogs,s,new(new MvpUiRepository(),s),NullLogger<OnlineViewModel>.Instance),s,repo,dialogs);}
    [Theory][InlineData("http://example.com")][InlineData("https://user:password@example.com")][InlineData("https://example.com/?token=secreto")][InlineData("https://example.com/#secreto")][InlineData("https://localhost/")][InlineData("https://192.168.1.2/")][InlineData("https://servidor.local./")][InlineData("file:///C:/archivo")][InlineData("https://example.com:444/")]
    public void DocumentaryUrlsRejectCredentialsQueriesAndLocalDestinations(string url)=>Assert.False(OnlineValidator.PublicUrl(url,out _));
    [Fact]public void DomainBelongsToExplicitBusinessSiteAndSocialProfilesRequireCorrectHost()
    {Assert.Equal("negocio.example.com",OnlineValidator.Domain("https://www.negocio.example.com./contacto"));Assert.Null(OnlineValidator.Identifier("INSTAGRAM","https://instagram.com.evil.example/user"));Assert.Equal("https://instagram.com/negocio",OnlineValidator.Identifier("INSTAGRAM","https://www.instagram.com/NEGOCIO/"));Assert.Equal("https://instagram.com/negocio",OnlineValidator.Identifier("INSTAGRAM","https://instagram.com/%6Eegocio/"));Assert.Equal("+50370000000",OnlineValidator.Identifier("WHATSAPP","7000-0000"));Assert.Equal("+50370000000",OnlineValidator.Identifier("WHATSAPP","+503 7000-0000"));}
    [Fact]public void PublicSourceAndVersionsAreMandatoryAndNoStateCanSimulateSending()
    {var r=Request();Assert.Null(OnlineValidator.Validate(r));Assert.NotNull(OnlineValidator.Validate(r with{Source=null}));Assert.NotNull(OnlineValidator.Validate(r with{Id=1,ExpectedVersion=[]}));Assert.NotNull(OnlineValidator.Source(Source() with{Obtained=DateTime.UtcNow.AddDays(2)}));Assert.NotNull(OnlineValidator.Validate(new ChangeOnlineState(Guid.NewGuid(),1,new byte[8],"CONTACTADO","Prueba")));Assert.NotNull(OnlineValidator.Validate(new ChangeOnlineState(Guid.NewGuid(),1,new byte[8],"CONVERTIDO","Prueba")));}
    [Fact]public void FrozenRequestsProtectVersionsDataAndRecoveryIdentities()
    {var r=Request() with{Id=1,ExpectedVersion=new byte[8],Source=null};var frozen=(SaveOnlineProspect)OnlineValidator.Freeze(r);var identity=OperationIdentity.Describe(r);Assert.True(OperationIdentity.IsValid(identity));r.Data.Name="Otro";r.ExpectedVersion[0]=9;Assert.Equal("Negocio",frozen.Data.Name);Assert.Equal(0,frozen.ExpectedVersion[0]);Assert.NotEqual(identity,OperationIdentity.Describe(r));foreach(var request in new object[]{new AddOnlineSource(Guid.NewGuid(),1,new byte[8],Source(),"Motivo"),new ChangeOnlineState(Guid.NewGuid(),1,new byte[8],"REVISADO","Motivo"),new BlockOnlineProspect(Guid.NewGuid(),1,new byte[8],"Motivo"),new ExcludeOnlineContact(Guid.NewGuid(),"INSTAGRAM","https://instagram.com/negocio/","Motivo"),new ConvertOnlineProspect(Guid.NewGuid(),1,new byte[8],1,new byte[8],"Motivo")}){Assert.Null(OnlineValidator.Validate(request));var f=OnlineValidator.Freeze(request);Assert.Null(OnlineValidator.Validate(f));Assert.Equal(OperationIdentity.Describe(request),OperationIdentity.Describe(f));}}
    [Fact]public void UntouchedLegacyContactsAndTerritoriesRemainExact()
    {var old=new OnlineProspectInput{Name="Histórico",Phone="teléfono histórico ",Email="correo heredado",Department="Antiguo",Municipality="Antiguo"};var d=OnlineValidator.Copy(old);d.Name="Nombre corregido";Assert.Null(OnlineValidator.Changed(d,old));var n=OnlineValidator.Normalize(d,old);Assert.Equal(old.Phone,n.Phone);Assert.Equal(old.Email,n.Email);Assert.Equal(old.Municipality,n.Municipality);d.Phone="inválido nuevo";Assert.NotNull(OnlineValidator.Changed(d,old));}
    [Fact]public async Task ViewingDoesNotGrantMaintenanceExclusionOrConversion()
    {var(vm,s,repo,_)=Create("COMERCIAL.VER","CLIENTES.VER");await vm.ReloadCommand.ExecuteAsync(null);vm.Selected=vm.Items.Single();await vm.OpenCommand.ExecuteAsync(null);Assert.False(vm.CanManage);Assert.False(vm.CanExclude);Assert.False(vm.CanConvert);var service=new OnlineService(repo,s);Assert.Equal("FORBIDDEN",(await service.SaveAsync(Request())).ErrorCode);Assert.Empty(repo.Writes);s.Clear();Assert.Empty(vm.Items);Assert.Empty(vm.Sources);Assert.Null(vm.Detail);Assert.False(vm.CanRead);}
    [Fact]public async Task LateDetailAndSearchCannotLeakAcrossSelectionsFiltersOrIdentities()
    {var(vm,s,repo,_)=Create();await vm.ReloadCommand.ExecuteAsync(null);vm.Selected=vm.Items.Single();var tcs=new TaskCompletionSource<OnlineProspectData?>(TaskCreationOptions.RunContinuationsAsynchronously);repo.PendingDetail=tcs.Task;var read=vm.OpenCommand.ExecuteAsync(null);vm.Selected=new(){Id=2};tcs.SetResult(repo.Prospect);await read;Assert.Null(vm.Detail);var pending=new TaskCompletionSource<MvpPage<OnlineProspectData>>(TaskCreationOptions.RunContinuationsAsynchronously);repo.PendingSearch=pending.Task;read=vm.ReloadCommand.ExecuteAsync(null);vm.Search="Otro";pending.SetResult(new([new(){Id=99,Name="Respuesta anterior"}],1));await read;Assert.Single(vm.Items);Assert.DoesNotContain(vm.Items,x=>x.Id==99);Assert.NotEqual("Otro",vm.Items.Single().Name);repo.PendingDetail=new TaskCompletionSource<OnlineProspectData?>().Task;var detail=new TaskCompletionSource<OnlineProspectData?>(TaskCreationOptions.RunContinuationsAsynchronously);repo.PendingDetail=detail.Task;var direct=new OnlineService(repo,s).ReadAsync(1);s.Clear();detail.SetResult(repo.Prospect);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>direct);}
    [Fact]public async Task LostSuppressionResponseRetriesSameGuidAndDoesNotGrantConsent()
    {var(vm,_,repo,dialogs)=Create();await vm.ReloadCommand.ExecuteAsync(null);vm.Selected=vm.Items.Single();await vm.OpenCommand.ExecuteAsync(null);repo.LoseResponse=true;dialogs.Action=async f=>{f.Fields.Single(x=>x.Key=="reason").Value="Solicitud de no contactar";f.Confirmed=true;await ((CommunityToolkit.Mvvm.Input.IAsyncRelayCommand)f.SaveCommand).ExecuteAsync(null);};await vm.BlockCommand.ExecuteAsync(null);Assert.True(vm.Operation.HasPending);Assert.Single(repo.Writes);var identity=OperationIdentity.Describe(repo.Writes[0]);repo.LoseResponse=false;await vm.Operation.RetryCommand.ExecuteAsync(null);Assert.Equal(2,repo.Writes.Count);Assert.All(repo.Writes,r=>Assert.Equal(identity,OperationIdentity.Describe(r)));Assert.False(vm.Operation.HasPending);}
    [Fact]public async Task DraftComparisonDropsResultsWhenInputsChange()
    {var(_,s,repo,_)=Create();var draft=new OnlineDraftModel(new(repo,s),repo.Prospect);var tcs=new TaskCompletionSource<MvpPage<OnlineMatch>>(TaskCreationOptions.RunContinuationsAsynchronously);repo.PendingMatch=tcs.Task;var task=draft.CheckMatchesCommand.ExecuteAsync(null);draft.Data.Name="Otro";tcs.SetResult(new([new(){Id=1,Name="Anterior"}],1));await task;Assert.Empty(draft.Matches);}
    private sealed class Dialogs:IMvpDialogService{public Func<MvpFormModel,Task>? Action;public async Task<bool> ShowAsync(MvpFormModel f){if(Action is not null)await Action(f);return false;}}
}
